"""Step 45 Part C report: partC/results.md from results.json and tuning.json (no model)."""
import os, json
from . import step45_partC as C
R = json.load(open(C.P('results.json'))); T = json.load(open(C.P('tuning.json')))
f = lambda g: f"{g[0] * 100:.1f}% ({g[1] * 100:.1f}-{g[2] * 100:.1f})"; pas = R['pass']
L = ['# Step 45, Part C: deterministic number checker on the free-text set A', '',
     f"**{'DOES PASS' if pas['passed'] else 'DOES NOT PASS'} the pre-registered rule** (reaches AUROC 0.80 at a 5% size change and a 1 mm head-circumference change, with at most 2% of harmless rewordings flagged). On the writer-made free-text test set the checker has AUROC 1.00 at every level tested (size x1.05 to x2.0, head circumference 1 to 10 mm) and flags **{f(R['harmless']['flagged'])}** of {R['harmless']['reports']} harmless rewordings. "
     f"Limit of detection: size 5% (breast, thyroid and both pooled), head circumference 1 mm (the lowest level tested). Cells: breast size {R['lod']['breast|size']['groups_per_level']['0.05']} and thyroid size {R['lod']['thyroid|size']['groups_per_level']['0.05']} groups at the 5% level (under 30: too small to compare on their own); **pooled breast + thyroid size {R['lod']['breast+thyroid|size']['groups_per_level']['0.05']} groups, head circumference {R['lod']['fetal|hc_mm']['groups_per_level']['1']} groups (both decided).** The pass is a pass on writer-made free text, not clinical validation.", '',
     'Pre-registration: [../PREREG.md](../PREREG.md). Code: `usmeta/step45_numchecker.py` (parser + score), `step45_partC.py`, `step45_partC_report.py`. Set A: [../freetext/results.md](../freetext/results.md).', '',
     '## What the checker is', '',
     'A regex parser reads the size (mm, cm, percent of the image width), head circumference, lesion count, side and BI-RADS / TI-RADS category from the reference and the candidate; score = 1 minus the largest deviation (relative size or head circumference beyond the tolerance, or 1 for a count / side / category mismatch); a candidate is flagged if score < 1. No model, no extractor.', '',
     '## Tolerance (fixed on dev/val of set A)', '', f"Grid: relative size tolerance {C.REL_GRID}, head circumference tolerance (mm) {C.HC_GRID}; target: at most 2% of harmless rewordings flagged. Result on {T['n_harmless']} dev/val harmless reports: the smallest tolerance (0 and 0 mm) already flags {T['chosen']['harmless_flagged'] * 100:.1f}%, so it was kept at 0. Flagged-by on dev/val: {T['flagged_by'] or 'nothing'}.", '',
     '## Test results (writer-made free text, one planted-error twin or graded twin per case, harmless = the same case\'s other-style reports)', '',
     '| quantity | value |', '|---|---|', f"| harmless rewordings flagged (all) | {f(R['harmless']['flagged'])} |"] + [f"| harmless flagged, {o} | {f(R['harmless'][o]['flagged'])} ({R['harmless'][o]['reports']} reports) |" for o in ('breast', 'thyroid', 'fetal')] + [
     f"| catch of the planted-error twins (all kinds of planted error) | {f(R['twin_catch']['all']['catch'])} ({R['twin_catch']['all']['n']} twins) |", '',
     '### Limit of detection (AUROC of the planted change vs the same case\'s harmless free-text reports; 0.80 rule; group bootstrap)', '', '| cell | level -> AUROC | groups per level | LOD (95% CI) | too small |', '|---|---|---|---|---|']
for k, v in R['lod'].items(): L.append(f"| {k} | " + ', '.join(f"{l}: {a:.2f}" for l, a in v['auroc'].items() if a is not None) + f" | {', '.join(str(g) for g in v['groups_per_level'].values())} | {v['lod']} ({v['lod_ci'][0]}-{v['lod_ci'][1]}) | {', '.join(map(str, v['too_small'])) or '—'} |")
L += ['', '### Catch of the planted-error twins by planted field (numbers and categories only: the checker reads nothing else)', '', '| field | twins | caught |', '|---|---|---|'] + [f"| {k} | {v['n']} | {v['catch'] * 100:.0f}% |" for k, v in R['twin_catch']['by_field'].items()]
L += ['', 'The checker catches every planted number, category (BI-RADS / TI-RADS) and head-circumference change and nothing else (lesion absent / present, position, orientation, plane, pathology, histology, halo, calcifications are not numbers): it is a complement to a fact extractor or a judge, not a replacement (Part F).', '',
      '## Deviations from the PREREG', '',
      '- Smaller set A than the PREREG (Part A results.md). Levels: size x1.05, x1.10, x1.25, x2.0 and head circumference 1, 2, 5, 10 mm (the Step 35 grids are finer).',
      '- **The test split was read twice by this part** (`test_access.log`: two `usmeta.step45_partC` lines). The first run gave per-organ size cells with 19-22 groups (under 30, "too small to compare"); a **pooled breast + thyroid size cell (41 groups) was added after seeing that** and the evaluation was re-run with a second logged read. The per-organ numbers did not change between the runs (deterministic checker, same reports).',
      '- Pass logic: the PREREG does not say how cells under 30 groups count; here the pass uses the pooled size cell and the head-circumference cell (both at least 30 groups).', '',
      '## Caveats', '',
      '- **AUROC 1.00 at every level is close to true by construction on this text:** the writer copies the supplied numbers verbatim, so a changed number is always visible to a parser, and harmless reports always carry the original number. Real radiologist or VLM text writes sizes as two dimensions ("3 cm x 2 cm"), in words, with different units or rounded; the parser has not been tested on such text.',
      '- The checker needs both reference and candidate to state the quantity (a missing number is not flagged); it cannot see omissions, wrong diagnoses or wrong locations (twin catch by field above).',
      '- Set A kept reports only after the gold and extras checks (Part A), so the harmless class contains only reports that state the supplied numbers; the 0% harmless-flagged rate describes those.', '']
open(C.P('results.md'), 'w').write('\n'.join(L)); print('wrote', len(L))
